# WITNESS ME!

*adjusts breathing apparatus*

You dare approach the gates of Valhalla with untested code? Very well. I shall forge tests worthy of the Immortan's standards. Do not, my friends, become addicted to passing tests. It will take hold of you.

```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts - the War Boys who serve the Immortan
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();
const mockOnComplete = vi.fn();
const mockOnCancel = vi.fn();

const mockCartItems = [
  { id: '1', name: 'Guzzoline', price: 49.99 },
  { id: '2', name: 'Aqua Cola', price: 25.00 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: mockCartItems,
    total: 74.99,
    clearCart: mockClearCart
  })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

const validShipping = {
  street: '123 Fury Road',
  city: 'Citadel',
  state: 'CA',
  zip: '90210'
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'Max Rockatansky'
};

describe('Checkout - THE GATES OF VALHALLA', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-WITNESS-ME' });
  });

  describe('Happy Path - You Will Ride Eternal, Shiny and Chrome', () => {
    it('completes full checkout flow successfully', async () => {
      const user = userEvent.setup();
      render(<Checkout onComplete={mockOnComplete} onCancel={mockOnCancel} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street/i), validShipping.street);
      await user.type(screen.getByLabelText(/city/i), validShipping.city);
      await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
      await user.type(screen.getByLabelText(/zip/i), validShipping.zip);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
      await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
      await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
      await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review and submit
      expect(screen.getByText(/guzzoline/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
      expect(mockOnComplete).toHaveBeenCalledWith('ORD-WITNESS-ME');
    });
  });

  describe('Validation - MEDIOCRE! submissions rejected', () => {
    it('shows error for empty street address', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('rejects invalid ZIP codes', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip/i), 'MEDIOCRE');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
    });
  });

  describe('Edge Cases - The Wasteland Has No Mercy', () => {
    it('shows empty cart message when cart is empty', () => {
      vi.mocked(require('./CartContext').useCart).mockReturnValue({
        items: [], total: 0, clearCart: mockClearCart
      });

      render(<Checkout onCancel={mockOnCancel} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  describe('Accessibility - All May Ride to Valhalla', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });
  });
});
```

